select i.* from sh_idle_item i left join sh_user u on i.user_id = u.id where i.idle_status = 1
and ( i.idle_name LIKE concat('%', #{findValue}, '%') or i.idle_details LIKE concat('%', #{findValue}, '%') or CAST(i.id AS CHAR) LIKE concat('%', #{findValue}, '%') or u.nickname LIKE concat('%', #{findValue}, '%') )
order by i.id desc limit #{begin}, #{nums}

